package org.jlinalg.cli;
import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import org.jlinalg.study.StudyOperationExecutor.Context;

/** User-configured prediction argument vectors; returned metadata is data, never executable instructions. */
final class StudyProteinPrediction {
    private final StudyVariantBatchCache cache=new StudyVariantBatchCache();
    record Batch(Path directory,List<Map<String,Object>> models,String identity,boolean reused,boolean complete,String reason) { }
    Batch run(Context c,Map<String,Object> policy,Map<String,Object> target,String sequence,Map<String,String> sequences,Path folder)throws IOException {
        var config=map(policy.get("prediction"));if(!Boolean.TRUE.equals(config.get("enabled")))return new Batch(folder,List.of(),"",false,false,"No compatible exact model and no configured prediction was enabled");if("online".equals(config.get("network"))&&!StudyPublicEvidence.blocked(c.study()).isEmpty())return new Batch(folder,List.of(),"",false,false,"Configured online prediction is disallowed by the study disclosure/download/network policy");Files.createDirectories(folder);
        var chains=new ArrayList<Object>();chains.add(Map.of("chain","A","sequence_id",text(target.getOrDefault("sequence_id","target")),"sequence_sha256",StudyFindingInventory.hash(sequence)));StringBuilder fasta=new StringBuilder(">A\n"+sequence+"\n");
        for(Object raw:list(target.get("partners"))){var partner=map(raw);String id=text(partner.get("sequence_id")),chain=text(partner.get("chain"));if(chain.equals("A"))throw new IllegalArgumentException("Partner chain cannot reuse the target's input chain A");String seq=sequences.get(id);if(seq==null)throw new IllegalArgumentException("Supply the exact partner sequence: "+id);fasta.append('>').append(chain).append('\n').append(seq).append('\n');chains.add(Map.of("chain",chain,"sequence_id",id,"sequence_sha256",StudyFindingInventory.hash(seq)));}
        var request=new LinkedHashMap<String,Object>();request.put("schema_version",1);request.put("protein_id",target.get("protein_id"));request.put("sequence_sha256",StudyFindingInventory.hash(sequence));request.put("chains",chains);request.put("prediction_inputs",target.getOrDefault("prediction_inputs",Map.of()));request.put("complex_justification",target.getOrDefault("complex_justification","Not a declared complex"));request.put("seeds",config.get("seeds"));request.put("software",config.get("software"));request.put("software_version",config.get("software_version"));request.put("model_version",config.get("model_version"));request.put("msa_provenance",config.get("msa_provenance"));request.put("template_provenance",config.get("template_provenance"));
        var provider=new LinkedHashMap<String,Object>(config);for(String key:List.of("enabled","timeout_seconds","maximum_output_bytes","maximum_output_files"))provider.remove(key);provider.put("adapter_type","protein_prediction_v1");var files=new LinkedHashMap<String,Object>();int ordinal=0;for(Object raw:list(config.get("command"))){String arg=text(raw);Path file=ordinal==0?executable(c.project(),arg):c.project().resolve(arg);if(!arg.contains("{")&&Files.isRegularFile(file))files.put(String.valueOf(ordinal),FollowupSupport.hash(file));ordinal++;}
        for(Object raw:list(config.get("input_files"))){String name=text(raw);Path file=c.project().resolve(name);if(!Files.isRegularFile(file))throw new IllegalArgumentException("Missing declared predictor input: "+name);files.put("input:"+name,FollowupSupport.hash(file));}
        String identity=StudyVariantBatchCache.identity(Map.of("provider",provider,"local_inputs",files),request);boolean reused=cache.reuse(c,identity,folder);
        if(!reused){Path input=folder.resolve("input.fasta"),json=folder.resolve("request.json");Files.writeString(input,fasta,StandardCharsets.UTF_8);Files.writeString(json,StudyAssistance.json(request));String original=FollowupSupport.hash(input);var command=new ArrayList<String>();for(Object raw:list(config.get("command"))){String arg=text(raw).replace("{input_fasta}",input.toAbsolutePath().toString()).replace("{request_json}",json.toAbsolutePath().toString()).replace("{output_dir}",folder.toAbsolutePath().toString()).replace("{sequence_sha256}",text(request.get("sequence_sha256"))).replace("{protein_id}",text(target.get("protein_id")));if(arg.contains("{")||arg.contains("}"))throw new IllegalArgumentException("Unknown configured prediction placeholder");if(!text(raw).contains("{")&&Files.isRegularFile(c.project().resolve(arg)))arg=c.project().resolve(arg).toAbsolutePath().toString();command.add(arg);}command.set(0,executable(c.project(),command.get(0)).toString());
            write(folder.resolve("execution.yaml"),Map.of("command",command,"request_sha256",FollowupSupport.hash(json),"input_fasta_sha256",original,"declared_software",config.get("software"),"declared_software_version",config.get("software_version"),"declared_model_version",config.get("model_version"),"execution_scope","Configured local process; the program's network/resource controls and software authenticity require separate verification"));
            Process process;try{process=new ProcessBuilder(command).directory(folder.toFile()).redirectErrorStream(true).start();}catch(IOException unavailable){return new Batch(folder,List.of(),identity,false,false,"Configured prediction executable unavailable; no prediction was claimed");}
            var executor=java.util.concurrent.Executors.newSingleThreadExecutor(r->{Thread t=new Thread(r,"protein-prediction-log");t.setDaemon(true);return t;});var drain=executor.submit(()->{try(var stream=process.getInputStream();var out=Files.newOutputStream(folder.resolve("console.txt"))){byte[] bytes=new byte[8192];long saved=0;boolean truncated=false;for(int read;(read=stream.read(bytes))>=0;){int keep=(int)Math.min(read,Math.max(0,1048576-saved));if(keep>0){out.write(bytes,0,keep);saved+=keep;}truncated|=keep<read;}if(truncated)out.write("\n[console truncated at 1 MiB; remaining output drained]\n".getBytes(StandardCharsets.UTF_8));}return true;});
            boolean ended;try{ended=process.waitFor(((Number)config.get("timeout_seconds")).intValue(),TimeUnit.SECONDS);if(!ended){process.descendants().forEach(ProcessHandle::destroyForcibly);process.destroyForcibly();process.waitFor(10,TimeUnit.SECONDS);}try{drain.get(10,TimeUnit.SECONDS);}catch(java.util.concurrent.ExecutionException|java.util.concurrent.TimeoutException failed){throw new IOException("Prediction log could not be sealed",failed);}}catch(InterruptedException interrupted){process.destroyForcibly();Thread.currentThread().interrupt();throw new IOException("Protein prediction interrupted",interrupted);}finally{executor.shutdownNow();}
            write(folder.resolve("process-result.yaml"),Map.of("completed",ended,"exit_code",ended?process.exitValue():-1,"actual_process_invoked",true,"scientific_software_identity","Source-declared; execution alone does not authenticate AlphaFold or its weights"));if(!original.equals(FollowupSupport.hash(input)))throw new IOException("Configured predictor changed its immutable input sequence");if(!ended)return new Batch(folder,List.of(),identity,false,false,"Configured prediction timed out; partial outputs are retained without a prediction-complete claim");if(process.exitValue()!=0)return new Batch(folder,List.of(),identity,false,false,"Configured prediction failed; partial outputs and console are retained");
        }
        Path result=folder.resolve(text(config.get("output_manifest"))).normalize();if(!result.startsWith(folder)||!Files.isRegularFile(result))return new Batch(folder,List.of(),identity,reused,false,"Configured prediction output manifest is missing or outside its output directory");if(Files.size(result)>2097152L)throw new IllegalArgumentException("Prediction output metadata exceeds 2 MiB");var output=StudyYaml.loadArtifact(result);StudyProteinInputs.unknown(output,java.util.Set.of("schema_version","sequence_sha256","models","provenance"),"prediction output");if(!Integer.valueOf(1).equals(output.get("schema_version")))throw new IllegalArgumentException("Prediction output requires schema_version: 1");if(!request.get("sequence_sha256").equals(output.get("sequence_sha256")))return new Batch(folder,List.of(),identity,reused,false,"Prediction output sequence hash differs from its immutable request");
        var models=new ArrayList<Map<String,Object>>();var seeds=new java.util.HashSet<Long>();for(Object raw:list(output.get("models"))){var m=new LinkedHashMap<>(map(raw));m.putIfAbsent("method",config.get("software"));m.putIfAbsent("model_version",config.get("model_version"));m.putIfAbsent("structure_kind","other_prediction");if(!m.containsKey("seed")&&list(config.get("seeds")).size()==1)m.put("seed",list(config.get("seeds")).get(0));if(m.get("seed") instanceof Number seed)seeds.add(seed.longValue());m= new LinkedHashMap<>(StudyProteinInputs.model(m));for(String key:StudyProteinInputs.MODEL_FILES)if(m.containsKey(key)){Path file=folder.resolve(text(m.get(key))).normalize();if(!file.startsWith(folder)||!Files.isRegularFile(file)||!file.toRealPath().startsWith(folder.toRealPath()))throw new IllegalArgumentException("Prediction model output missing or escapes its directory: "+key);m.put(key,file.toAbsolutePath().toString());}m.put("source","configured_prediction");m.put("source_sequence_sha256",request.get("sequence_sha256"));models.add(m);}
        long bytes=0,count=0;try(var paths=Files.walk(folder)){for(Path file:paths.filter(Files::isRegularFile).toList()){bytes+=Files.size(file);count++;if(bytes>((Number)config.get("maximum_output_bytes")).longValue()||count>((Number)config.get("maximum_output_files")).longValue())return new Batch(folder,List.of(),identity,reused,false,"Prediction output exceeds registered storage bounds; raw files are retained and cannot be promoted or cached as complete");}}
        boolean complete=!models.isEmpty()&&list(config.get("seeds")).stream().map(v->((Number)v).longValue()).allMatch(seeds::contains);return new Batch(folder,List.copyOf(models),identity,reused,complete,complete?"Configured prediction outputs retained for sequence/structure validation":"Configured prediction does not cover every declared seed; no favorable subset is promoted");
    }
    static void seal(Batch batch)throws IOException{if(batch.complete()&&!batch.reused())StudyVariantBatchCache.seal(batch.directory(),batch.identity());}
    static Path executable(Path root,String value){Path file=root.resolve(value);if(Files.isRegularFile(file))return file.toAbsolutePath();String path=System.getenv("PATH");if(path!=null)for(String directory:path.split(java.util.regex.Pattern.quote(java.io.File.pathSeparator))){if(directory.isBlank())continue;for(String extension:System.getProperty("os.name").toLowerCase(java.util.Locale.ROOT).contains("win")?List.of("",".exe",".cmd",".bat"):List.of("")){Path candidate=Path.of(directory).resolve(value+extension);if(Files.isRegularFile(candidate))return candidate.toAbsolutePath();}}return file;}
}
